-- ======================================================================
-- supabase/migrations/0001_schema.sql
-- ======================================================================

-- DeshRide schema. Plain Postgres: the only Supabase-specific call is
-- auth.uid(), reached solely through app.current_user_id() (0003), so the
-- database can move to RDS or self-hosted Postgres by swapping that function.

create extension if not exists pgcrypto;
create schema if not exists app;

-- Public face of a user: what other riders and drivers may see.
create table if not exists public.profiles (
  id text primary key,
  name text not null default '',
  photo text,
  bio text check (bio is null or char_length(bio) <= 200),
  prefs jsonb,
  member_since timestamptz not null default now(),
  verified_phone boolean not null default false,
  verified_nid boolean not null default false,
  is_driver boolean not null default false,
  updated_at timestamptz not null default now()
);

-- Private details: only the owner can read these (phone, NIDs, payout wallet).
create table if not exists public.profiles_private (
  id text primary key references public.profiles(id) on delete cascade,
  phone text,
  driver jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists public.rides (
  id text primary key,
  driver_id text not null references public.profiles(id),
  -- Snapshot shown on listings (name, rating, car, plate…). Never a phone number.
  driver jsonb not null,
  from_spot jsonb not null,
  to_spot jsonb not null,
  stops jsonb not null default '[]'::jsonb,
  departure timestamptz not null,
  seats_total int not null check (seats_total between 1 and 8),
  price_per_seat int not null check (price_per_seat > 0),
  car text not null,
  luggage text not null check (luggage in ('small', 'medium', 'large')),
  rules jsonb not null default '[]'::jsonb,
  note text,
  instant_book boolean not null default false,
  status text not null default 'active' check (status in ('active', 'completed', 'cancelled')),
  series_id text,
  created_at timestamptz not null default now()
);
create index if not exists rides_departure_idx on public.rides (departure) where status = 'active';
create index if not exists rides_driver_idx on public.rides (driver_id);

create table if not exists public.bookings (
  id text primary key,
  ride_id text not null references public.rides(id),
  guest_id text not null references public.profiles(id),
  guest_name text not null,
  seats int not null check (seats > 0),
  pay_method text not null check (pay_method in ('bkash', 'nagad', 'card')),
  status text not null check (status in ('pending', 'accepted', 'declined', 'cancelled', 'expired')),
  pay_status text not null check (pay_status in ('unpaid', 'held', 'releasing', 'released', 'refunded')),
  message text,
  rating int check (rating between 1 and 5),
  release_at timestamptz,
  refund_pct int,
  pickup_idx int,
  dropoff_idx int,
  fare_per_seat int,
  expires_at timestamptz,
  via_request boolean not null default false,
  responded_at timestamptz,
  no_show text check (no_show in ('guest', 'driver')),
  driver_rating int check (driver_rating between 1 and 5),
  created_at timestamptz not null default now()
);
create index if not exists bookings_ride_idx on public.bookings (ride_id);
create index if not exists bookings_guest_idx on public.bookings (guest_id);

create table if not exists public.messages (
  id text primary key,
  booking_id text not null references public.bookings(id),
  sender_id text not null references public.profiles(id),
  sender_name text not null,
  text text not null check (char_length(text) <= 2000),
  flags text[] not null default '{}',
  -- clock_timestamp, not now(): messages sent in one transaction still order correctly.
  created_at timestamptz not null default clock_timestamp()
);
create index if not exists messages_booking_idx on public.messages (booking_id, created_at);

create table if not exists public.notifications (
  id text primary key default ('ntf-' || substr(md5(gen_random_uuid()::text), 1, 10)),
  user_id text not null references public.profiles(id),
  kind text not null,
  booking_id text,
  ride_id text,
  request_id text,
  read boolean not null default false,
  created_at timestamptz not null default now()
);
create index if not exists notifications_user_idx on public.notifications (user_id, created_at desc);
-- One "trip tomorrow" reminder per person per booking.
create unique index if not exists notifications_trip_once
  on public.notifications (user_id, kind, booking_id) where kind = 'tripTomorrow';

create table if not exists public.ride_alerts (
  id text primary key,
  user_id text not null references public.profiles(id),
  from_district text,
  to_district text,
  created_at timestamptz not null default now(),
  unique (user_id, from_district, to_district)
);

create table if not exists public.blocks (
  blocker_id text not null references public.profiles(id),
  target_id text not null references public.profiles(id),
  target_name text not null,
  created_at timestamptz not null default now(),
  primary key (blocker_id, target_id)
);

create table if not exists public.reports (
  id text primary key,
  reporter_id text not null references public.profiles(id),
  target_id text not null,
  target_name text not null,
  reason text not null check (reason in ('unsafeDriving', 'harassment', 'offAppPayment', 'noShow', 'other')),
  note text,
  booking_id text,
  created_at timestamptz not null default now()
);

create table if not exists public.ride_requests (
  id text primary key,
  rider_id text not null references public.profiles(id),
  rider_name text not null,
  from_spot jsonb not null,
  to_spot jsonb not null,
  date date not null,
  seats int not null check (seats between 1 and 6),
  note text,
  status text not null default 'open' check (status in ('open', 'closed')),
  created_at timestamptz not null default now()
);

create table if not exists public.ride_request_offers (
  request_id text not null references public.ride_requests(id),
  ride_id text not null references public.rides(id),
  driver_id text not null references public.profiles(id),
  created_at timestamptz not null default now(),
  primary key (request_id, ride_id)
);

create table if not exists public.driver_ratings (
  booking_id text primary key references public.bookings(id),
  driver_id text not null,
  stars int not null check (stars between 1 and 5),
  created_at timestamptz not null default now()
);

create table if not exists public.passenger_ratings (
  booking_id text primary key references public.bookings(id),
  guest_id text not null,
  stars int not null check (stars between 1 and 5),
  created_at timestamptz not null default now()
);

create table if not exists public.strikes (
  user_id text primary key,
  cancelled int not null default 0,
  no_shows int not null default 0
);

create table if not exists public.user_stats (
  user_id text primary key,
  points int not null default 0,
  driver_trips int not null default 0,
  guest_trips int not null default 0,
  seats_filled int not null default 0
);

-- ======================================================================
-- supabase/migrations/0002_rls.sql
-- ======================================================================

-- Row-level security. Reads are filtered per user; every write goes through
-- the security-definer functions in 0003, so tables grant no insert/update.

-- The one place that knows how the signed-in user is identified. On Supabase
-- that is auth.uid(); after a move to AWS, swap this body to read the user id
-- from a verified Cognito JWT claim (e.g. current_setting('request.jwt.claim.sub')).
create or replace function app.current_user_id() returns text
language sql stable as $$
  select auth.uid()::text
$$;

create or replace function app.require_user() returns text
language plpgsql stable as $$
declare uid text := app.current_user_id();
begin
  if uid is null then
    raise exception 'Sign in first.' using errcode = '28000';
  end if;
  return uid;
end $$;

create or replace function app.is_blocked_between(a text, b text) returns boolean
language sql stable security definer set search_path = public, app as $$
  select exists (
    select 1 from public.blocks
    where (blocker_id = a and target_id = b) or (blocker_id = b and target_id = a)
  )
$$;

create or replace function app.can_see_booking(bid text) returns boolean
language sql stable security definer set search_path = public, app as $$
  select exists (
    select 1 from public.bookings bk join public.rides r on r.id = bk.ride_id
    where bk.id = bid and app.current_user_id() in (bk.guest_id, r.driver_id)
  )
$$;

alter table public.profiles enable row level security;
alter table public.profiles_private enable row level security;
alter table public.rides enable row level security;
alter table public.bookings enable row level security;
alter table public.messages enable row level security;
alter table public.notifications enable row level security;
alter table public.ride_alerts enable row level security;
alter table public.blocks enable row level security;
alter table public.reports enable row level security;
alter table public.ride_requests enable row level security;
alter table public.ride_request_offers enable row level security;
alter table public.driver_ratings enable row level security;
alter table public.passenger_ratings enable row level security;
alter table public.strikes enable row level security;
alter table public.user_stats enable row level security;

drop policy if exists profiles_read on public.profiles;
create policy profiles_read on public.profiles for select to authenticated using (true);

drop policy if exists private_read_own on public.profiles_private;
create policy private_read_own on public.profiles_private for select to authenticated
  using (id = app.current_user_id());

drop policy if exists rides_read on public.rides;
create policy rides_read on public.rides for select to authenticated
  using (driver_id = app.current_user_id() or not app.is_blocked_between(app.current_user_id(), driver_id));

drop policy if exists bookings_read on public.bookings;
create policy bookings_read on public.bookings for select to authenticated
  using (
    guest_id = app.current_user_id()
    or exists (select 1 from public.rides r where r.id = ride_id and r.driver_id = app.current_user_id())
  );

drop policy if exists messages_read on public.messages;
create policy messages_read on public.messages for select to authenticated
  using (app.can_see_booking(booking_id));

drop policy if exists notifications_read on public.notifications;
create policy notifications_read on public.notifications for select to authenticated
  using (user_id = app.current_user_id());

drop policy if exists alerts_read on public.ride_alerts;
create policy alerts_read on public.ride_alerts for select to authenticated
  using (user_id = app.current_user_id());

drop policy if exists blocks_read on public.blocks;
create policy blocks_read on public.blocks for select to authenticated
  using (blocker_id = app.current_user_id());

drop policy if exists requests_read on public.ride_requests;
create policy requests_read on public.ride_requests for select to authenticated
  using (
    rider_id = app.current_user_id()
    or (status = 'open' and not app.is_blocked_between(app.current_user_id(), rider_id))
  );

drop policy if exists offers_read on public.ride_request_offers;
create policy offers_read on public.ride_request_offers for select to authenticated
  using (
    driver_id = app.current_user_id()
    or exists (select 1 from public.ride_requests q where q.id = request_id and q.rider_id = app.current_user_id())
  );

drop policy if exists stats_read_own on public.user_stats;
create policy stats_read_own on public.user_stats for select to authenticated
  using (user_id = app.current_user_id());

-- reports, ratings and strikes have no read policy: only the aggregates in
-- public.trust_summary (0003) are exposed.

grant usage on schema public to authenticated;
grant usage on schema app to authenticated;
grant select on public.profiles, public.profiles_private, public.rides, public.bookings, public.messages,
  public.notifications, public.ride_alerts, public.blocks, public.ride_requests,
  public.ride_request_offers, public.user_stats to authenticated;
revoke insert, update, delete on all tables in schema public from authenticated, anon;
revoke all on all tables in schema public from anon;

